#!/usr/bin/env bash
set -euox pipefail

function repo_root() {
  git rev-parse --show-toplevel
}

function project_version() {
  # VERSION derived from CHANGELOG and automated release library
  fullVersion=$(<"$(repo_root)/VERSION")
  # Only use base version (strip any suffix, e.g. "-dev" or build number)
  if [[ "$fullVersion" == *-* ]]; then
    echo "${fullVersion%%-*}"
  else
    echo "$fullVersion"
  fi
}

# Create a clean copy of the source code for build
cp -a /src /build
git config --global --add safe.directory /build
cd /build
git clean -fdx || :
# Copy the VERSION file generated by the CI to the build directory
cp /src/VERSION /build/VERSION

# Restore packages
dotnet restore

# test (single run, deterministic junit + coverage outputs)
dotnet build
dotnet test \
  --logger:"junit;LogFileName=TestResults.xml" \
  --collect:"Code Coverage;Format=Cobertura" \
  --results-directory:"/build/TestResults"

# Ensure junit file exists at the exact location expected by outer build.sh
if [ ! -s /build/TestResults.xml ]; then
  # fallback: some logger versions write under results directory
  found_junit="$(find /build/TestResults -type f -name 'TestResults.xml' | head -n 1 || true)"
  if [ -n "$found_junit" ]; then
    cp "$found_junit" /build/TestResults.xml
  fi
fi

if [ ! -s /build/TestResults.xml ]; then
  echo "ERROR: JUnit report was not created at /build/TestResults.xml"
  find /build/TestResults -maxdepth 3 -type f -print || true
  exit 1
fi

cp /build/TestResults/*/*.cobertura.xml /build/Coverage.xml

VERSION=$(project_version)
dotnet build api-dotnet.sln --configuration Release /p:AssemblyVersion="$VERSION"

mkdir nugetPackages
dotnet pack -o ./nugetPackages --version-suffix "$VERSION"
